import re
p='xtask/src/site.rs'
s=open(p).read()
s=s.replace('''fn str_of<'a>''','''/// Escapes `text` and turns each `[[term]]` into a link to that term's Glossary entry, so a term is
/// defined once and every other mention points at the definition.
fn linked(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(start) = rest.find("[[") {
        let Some(len) = rest[start + 2..].find("]]") else {
            break;
        };
        let term = &rest[start + 2..start + 2 + len];
        out.push_str(&escape(&rest[..start]));
        let _ = write!(
            out,
            "<a href=\\"#term-{}\\">{}</a>",
            escape(&term.replace(' ', "-")),
            escape(term)
        );
        rest = &rest[start + 2 + len + 2..];
    }
    out.push_str(&escape(rest));
    out
}

fn str_of<'a>''',1)
reps=[
('escape(str_of(t, "text", &what)?),\n            cites(t, &what, known)?\n        );\n    }\n    body.push_str("</dl><h3>What firstmate is','linked(str_of(t, "text", &what)?),\n            cites(t, &what, known)?\n        );\n    }\n    body.push_str("</dl><h3>What firstmate is'),
('escape(str_of(d, "text", &what)?)','linked(str_of(d, "text", &what)?)'),
('escape(str_of(summary, "text", &summary_what)?)','linked(str_of(summary, "text", &summary_what)?)'),
('escape(str_of(t, "trigger", &what)?)','linked(str_of(t, "trigger", &what)?)'),
('escape(guard),','linked(guard),'),
('escape(failure)','linked(failure)'),
('let definition = escape(str_of(entry, "definition", &what)?);','let definition = linked(str_of(entry, "definition", &what)?);'),
('let text = escape(str_of(item, "text", &what)?);','let text = linked(str_of(item, "text", &what)?);'),
('let text = escape(str_of(item, "text", what)?);','let text = linked(str_of(item, "text", what)?);'),
]
for a,b in reps:
    assert s.count(a)==1,a
    s=s.replace(a,b)
open(p,'w').write(s)
